package com.tiny.browser;import android.os.*;import android.webkit.*;import android.widget.*;public class MainActivity extends android.app.Activity{public void onCreate(Bundle b){super.onCreate(b);WebView w=new WebView(this);w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);w.setWebViewClient(new WebViewClient());setContentView(w);w.loadUrl("https://www.google.com");}}
